    static final Map<String, Integer> COMPLETION_VARBITS;
    static
    {
        List<Activity> activities = new ArrayList<>();
        Map<String, Integer> varbits = new LinkedHashMap<>();
        add(activities, varbits, "ardougne", "Ardougne",
            VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE);
        add(activities, varbits, "desert", "Desert",
            VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE);
        add(activities, varbits, "falador", "Falador",
            VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE);
        add(activities, varbits, "fremennik", "Fremennik",
            VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE);
        add(activities, varbits, "kandarin", "Kandarin",
            VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE);
        add(activities, varbits, "karamja", "Karamja",
            VarbitID.ATJUN_EASY_DONE, VarbitID.ATJUN_MED_DONE, VarbitID.ATJUN_HARD_DONE, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE);
        add(activities, varbits, "kourend_kebos", "Kourend & Kebos",
            VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE);
        add(activities, varbits, "lumbridge_draynor", "Lumbridge & Draynor",
            VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE);
        add(activities, varbits, "morytania", "Morytania",
            VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE);
        add(activities, varbits, "varrock", "Varrock",
            VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE);
        add(activities, varbits, "western_provinces", "Western Provinces",
            VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE);
        add(activities, varbits, "wilderness", "Wilderness",
            VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE);
        ACTIVITIES = Collections.unmodifiableList(activities);
        COMPLETION_VARBITS = Collections.unmodifiableMap(varbits);
    }

    private static void add(List<Activity> activities, Map<String, Integer> varbits,
        String region, String name, int... flags)
    {
        String[] tiers = {"Easy", "Medium", "Hard", "Elite"};
        for (int i = 0; i < tiers.length; i++)
        {
            String id = region + "_" + tiers[i].toLowerCase(Locale.ROOT);
            activities.add(new Activity(id, name + " - " + tiers[i]));
            varbits.put(id, flags[i]);
        }
    }

    private DiaryCatalog() { }
}

package com.osrsrandomizer;

import java.util.*;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.client.plugins.achievementdiary.*;

/** Evaluates tier requirements using one client-thread snapshot, never on Swing. */
final class DiaryRequirements
{
    private static final Map<String, List<Requirement>> RULES = DiaryRequirementsData.rules();
    private static final Map<String, List<DiaryTask>> TASKS = DiaryRequirementsData.tasks();

    static final class Evaluation
    {
        final Map<String, String> reasons;
        final Map<String, String> details;
        Evaluation(Map<String, String> reasons, Map<String, String> details)
        {
            this.reasons = Collections.unmodifiableMap(new LinkedHashMap<>(reasons));
            this.details = Collections.unmodifiableMap(new LinkedHashMap<>(details));
        }
    }

    static Set<Quest> quests()
    {
        Set<Quest> quests = EnumSet.noneOf(Quest.class);
        RULES.values().forEach(rules -> rules.forEach(rule -> collectQuests(rule, quests)));
        return Collections.unmodifiableSet(quests);
    }

    private static void collectQuests(Requirement rule, Set<Quest> quests)
    {
        if (rule instanceof QuestRequirement) quests.add(((QuestRequirement) rule).getQuest());
        if (rule instanceof OrRequirement)
            ((OrRequirement) rule).getRequirements().forEach(child -> collectQuests(child, quests));
    }

    static Map<String, String> evaluate(Map<Skill, Integer> levels, Map<Quest, QuestState> quests,
        Integer combat, Integer questPoints)
    {
        return evaluate(levels, quests, combat, questPoints, id -> null, id -> null).reasons;
    }

    static Evaluation evaluate(Map<Skill, Integer> levels, Map<Quest, QuestState> quests,
        Integer combat, Integer questPoints, java.util.function.IntFunction<Integer> varps,
        java.util.function.IntFunction<Integer> varbits)
    {
        Map<String, String> results = new LinkedHashMap<>();
        Map<String, String> details = new LinkedHashMap<>();
        TASKS.forEach((id, tasks) ->
        {
            Set<String> missing = new LinkedHashSet<>();
            Set<String> lines = new LinkedHashSet<>();
            boolean unknown = false;
            for (DiaryTask task : tasks)
            {
                if (task.completed(varps, varbits)) continue;
                List<String> taskMissing = new ArrayList<>();
                for (Requirement rule : task.requirements)
                {
                    Boolean result = satisfied(rule, levels, quests, combat, questPoints);
                    unknown |= result == null;
                    if (!Boolean.TRUE.equals(result))
                    {
                        taskMissing.add(describeCurrent(rule, levels, quests, combat, questPoints));
                        if (Boolean.FALSE.equals(result)) missing.add(describe(rule));
                    }
                }
                if (!taskMissing.isEmpty()) lines.add(task.name + "\n" + String.join("\n", taskMissing));
            }
            if (id.equals("lumbridge_draynor_elite") || id.equals("falador_elite"))
            {
                boolean lumbridge = id.equals("lumbridge_draynor_elite");
                Integer bits = varps.apply(lumbridge
                    ? net.runelite.api.gameval.VarPlayerID.LUMB_DRAY_ACHIEVEMENT_DIARY2
                    : net.runelite.api.gameval.VarPlayerID.FALADOR_ACHIEVEMENT_DIARY2);
                boolean done = bits != null && ((bits >>> (lumbridge ? 9 : 8)) & 1) == 1;
                boolean skillCape = !lumbridge && levels.entrySet().stream()
                    .anyMatch(e -> e.getKey() != Skill.OVERALL && e.getValue() != null && e.getValue() >= 99);
                if (!done && !skillCape)
                {
                    Integer maxPoints = varbits.apply(net.runelite.api.gameval.VarbitID.QP_MAX);
                    boolean qpUnknown = maxPoints == null || maxPoints <= 0 || questPoints == null;
                    if (qpUnknown || questPoints < maxPoints)
                    {
                        boolean skillsUnknown = !lumbridge && Arrays.stream(Skill.values())
                            .filter(s -> s != Skill.OVERALL).anyMatch(s -> levels.get(s) == null);
                        unknown |= qpUnknown || skillsUnknown;
                        String requirement = lumbridge ? "Quest point cape" : "Any level 99 skill or quest point cape";
                        if (!qpUnknown && !skillsUnknown) missing.add(requirement);
                        lines.add("Perform the cape emote\n" + requirement + "\nQuest points: "
                            + current(questPoints) + " / " + (maxPoints == null || maxPoints <= 0 ? "?" : maxPoints));
                    }
                }
            }
            results.put(id, unknown ? "Waiting for skill/quest data" : missing.isEmpty() ? null : String.join("; ", missing));
            details.put(id, lines.isEmpty() ? "No missing tracked requirements for unfinished tasks." : String.join("\n\n", lines));
        });
        return new Evaluation(results, details);
    }

    private static String describeCurrent(Requirement rule, Map<Skill, Integer> levels,
        Map<Quest, QuestState> quests, Integer combat, Integer questPoints)
    {
        if (rule instanceof SkillRequirement)
        {
            SkillRequirement skill = (SkillRequirement) rule;
            return skill.getSkill().getName() + ": " + current(levels.get(skill.getSkill())) + " / " + skill.getLevel();
        }
        if (rule instanceof QuestRequirement)
        {
            QuestRequirement quest = (QuestRequirement) rule;
            QuestState state = quests.get(quest.getQuest());
            return describe(rule) + " (" + (state == null ? "unknown" : state == QuestState.NOT_STARTED ? "not started"
                : state == QuestState.IN_PROGRESS ? "in progress" : "completed") + ")";
        }
        if (rule instanceof OrRequirement)
        {
            List<String> options = new ArrayList<>();
            ((OrRequirement) rule).getRequirements().forEach(child ->
                options.add(describeCurrent(child, levels, quests, combat, questPoints)));
            return String.join(" OR ", options);
        }
        if (rule instanceof CombatLevelRequirement)
            return "Combat: " + current(combat) + " / " + ((CombatLevelRequirement) rule).getLevel();
        if (rule instanceof QuestPointRequirement)
            return "Quest points: " + current(questPoints) + " / " + ((QuestPointRequirement) rule).getQp();
        return describe(rule);
    }

    private static String current(Integer value) { return value == null ? "?" : value.toString(); }

    static Boolean satisfied(Requirement rule, Map<Skill, Integer> levels, Map<Quest, QuestState> quests,
        Integer combat, Integer questPoints)
    {
        if (rule instanceof SkillRequirement)
        {
            SkillRequirement skill = (SkillRequirement) rule;
            Integer level = levels.get(skill.getSkill());
            return level == null ? null : level >= skill.getLevel();
        }
        if (rule instanceof QuestRequirement)
        {
            QuestRequirement quest = (QuestRequirement) rule;
            QuestState state = quests.get(quest.getQuest());
            return state == null ? null : quest.isStarted() ? state != QuestState.NOT_STARTED : state == QuestState.FINISHED;
        }
        if (rule instanceof OrRequirement)
        {
            boolean unknown = false;
            for (Requirement child : ((OrRequirement) rule).getRequirements())
            {
                Boolean result = satisfied(child, levels, quests, combat, questPoints);
                if (Boolean.TRUE.equals(result)) return true;
                unknown |= result == null;
            }
            return unknown ? null : Boolean.FALSE;
        }
        if (rule instanceof CombatLevelRequirement)
            return combat == null ? null : combat >= ((CombatLevelRequirement) rule).getLevel();
        if (rule instanceof QuestPointRequirement)
            return questPoints == null ? null : questPoints >= ((QuestPointRequirement) rule).getQp();
        return null;
    }

    private static String describe(Requirement rule)
    {
        if (rule instanceof QuestRequirement)
        {
            QuestRequirement quest = (QuestRequirement) rule;
            return (quest.isStarted() ? "Start " : "Complete ") + quest.getQuest().getName();
        }
        if (rule instanceof OrRequirement)
        {
            List<String> options = new ArrayList<>();
            ((OrRequirement) rule).getRequirements().forEach(child -> options.add(describe(child)));
            return String.join(" or ", options);
        }
        return rule.toString();
    }

    private DiaryRequirements() { }
}

package com.osrsrandomizer;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.IntFunction;
import net.runelite.client.plugins.achievementdiary.Requirement;

/** A task's completion flag, independent of intermediate multi-stage progress. */
final class DiaryTask
{
    final String name;
    final boolean varbit;
    final int variable;
    final int thresholdOrBit;
    final List<Requirement> requirements;

    DiaryTask(String name, boolean varbit, int variable, int thresholdOrBit, Requirement... requirements)
    {
        this.name = name;
        this.varbit = varbit;
        this.variable = variable;
        this.thresholdOrBit = thresholdOrBit;
        this.requirements = Collections.unmodifiableList(Arrays.asList(requirements.clone()));
    }

    boolean completed(IntFunction<Integer> varps, IntFunction<Integer> varbits)
    {
        Integer value = (varbit ? varbits : varps).apply(variable);
        // A failed read must never waive requirements. Unsigned shift includes bit 31.
        return value != null && (varbit ? value >= thresholdOrBit : ((value >>> thresholdOrBit) & 1) == 1);
    }
}

package com.osrsrandomizer;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Deque;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;

/** History independent for every category, restored when a character logs in. Used on the Swing EDT. */
public final class DrawEngine
{
    private final Random random;
    private final Map<Category, Deque<String>> recent = new EnumMap<>(Category.class);

    public DrawEngine(Random random)
    {
        this.random = random;
        for (Category category : Category.values()) recent.put(category, new ArrayDeque<>());
    }

    void reset() { for (Deque<String> history : recent.values()) history.clear(); }

    void restore(Category category, Collection<Activity> newestFirst)
    {
        Deque<String> history = recent.get(category);
        history.clear();
        for (Activity activity : newestFirst)
        {
            history.addFirst(activity.getId());
            if (history.size() == 3) break;
        }
    }

    public Optional<Activity> draw(Category category, Collection<String> selected)
    {
        List<Activity> pool = category.getActivities().stream()
            .filter(activity -> selected.contains(activity.getId())).collect(Collectors.toList());
        if (pool.isEmpty()) return Optional.empty();

        Deque<String> history = recent.get(category);
        List<String> exclusions = new ArrayList<>(history); // oldest first
        List<Activity> available;
        while (true)
        {
            Set<String> blocked = new HashSet<>(exclusions);
            available = pool.stream().filter(a -> !blocked.contains(a.getId())).collect(Collectors.toList());
            if (!available.isEmpty()) break;
            exclusions.remove(0);
        }
        Activity result = available.get(random.nextInt(available.size()));
        history.addLast(result.getId());
        while (history.size() > 3) history.removeFirst();
        return Optional.of(result);
    }
}

package com.osrsrandomizer;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.stream.Collectors;

/** Newest first. Repeated results are intentional; unknown catalogue IDs are ignored. */
final class HistoryCodec
{
    static List<Activity> decode(Category category, String value)
    {
        List<Activity> result = new ArrayList<>();
        if (value == null) return result;
        for (String id : value.split(","))
        {
            for (Activity activity : category.getActivities())
                if (activity.getId().equals(id)) { result.add(activity); break; }
            if (result.size() == 5) break;
        }
        return result;
    }

    static String encode(Collection<Activity> history)
    {
        return history.stream().limit(5).map(Activity::getId).collect(Collectors.joining(","));
    }
}

