@PluginDescriptor(name = "OSRS Randomizer", description = "Choose your next skill, boss, raid or diary",
    tags = {"random", "skills", "bosses", "raids", "diaries"})
public class OsrsRandomizerPlugin extends Plugin
{
    private static final String CONFIG_GROUP = "osrsrandomizer";
    @Inject private ClientToolbar toolbar;
    @Inject private ConfigManager configManager;
    @Inject private OsrsRandomizerConfig config;
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    private final AtomicInteger generation = new AtomicInteger();
    private QuestAvailability lastSnapshot = QuestAvailability.unavailable();
    private int ticksUntilRefresh;
    private NavigationButton navigation;
    private RandomizerPanel panel;
    // Accessed only on the EDT, including queued lifecycle callbacks.
    private boolean active;

    @Provides
    OsrsRandomizerConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(OsrsRandomizerConfig.class);
    }

    @Override
    protected void startUp()
    {
        int token = generation.incrementAndGet();
        SwingUtilities.invokeLater(() ->
        {
            if (token != generation.get()) return;
            if (active) return;
            active = true;
            SelectionStore store = new SelectionStore()
            {
                public boolean questFilterEnabled()
                {
                    return config.questFilterEnabled();
                }

                public Set<String> load(Category category)
                {
                    return SelectionCodec.decode(category,
                        configManager.getConfiguration(CONFIG_GROUP, category.getKey()));
                }

                public void save(Category category, Set<String> selected)
                {
                    configManager.setConfiguration(CONFIG_GROUP, category.getKey(), SelectionCodec.encode(selected));
                }

                public String loadHistory(long account, Category category)
                {
                    return configManager.getConfiguration(CONFIG_GROUP, historyKey(account, category));
                }

                public void saveHistory(long account, Category category, String value)
                {
                    configManager.setConfiguration(CONFIG_GROUP, historyKey(account, category), value);
                }

                private String historyKey(long account, Category category)
                {
                    return "historyV1_" + Long.toUnsignedString(account) + "_" + category.getKey();
                }
            };
            panel = new RandomizerPanel(new DrawEngine(new Random()), store);
            navigation = NavigationButton.builder().tooltip("OSRS Randomizer")
                .icon(ImageUtil.loadImageResource(OsrsRandomizerPlugin.class, "navigation.png"))
                .priority(8).panel(panel).build();
            toolbar.addNavigation(navigation);
            clientThread.invokeLater(() ->
            {
                if (token != generation.get()) return;
                lastSnapshot = null;
                ticksUntilRefresh = 0;
                // Query after the next server tick, once login variables are populated.
                if (client.getGameState() != GameState.LOGGED_IN) publish(QuestAvailability.unavailable());
            });
        });
    }

    @Override
    protected void shutDown()
    {
        generation.incrementAndGet();
        SwingUtilities.invokeLater(() ->
        {
            active = false;
            if (panel != null) panel.dispose();
            panel = null;
            if (navigation != null) toolbar.removeNavigation(navigation);
            navigation = null;
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!CONFIG_GROUP.equals(event.getGroup()) || !"questFilter".equals(event.getKey())) return;
        int token = generation.get();
        SwingUtilities.invokeLater(() ->
        {
            if (token == generation.get() && active && panel != null)
                panel.setQuestFilterEnabled(config.questFilterEnabled());
        });
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        ticksUntilRefresh = 0;
        // Also invalidate during hopping/reconnection; never reuse another session's data.
        if (event.getGameState() != GameState.LOGGED_IN) publish(QuestAvailability.unavailable());
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null) return;
        if (ticksUntilRefresh-- > 0) return;
        ticksUntilRefresh = 9;
        Map<Quest, QuestState> states = new EnumMap<>(Quest.class);
        for (Quest quest : QuestAvailability.quests())
        {
            try { states.put(quest, quest.getState(client)); }
            catch (RuntimeException ignored) { /* Missing data remains unknown and is retried. */ }
        }
        Boolean wildernessMediumComplete = null;
        try
        {
            wildernessMediumComplete = client.getVarbitValue(VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE) == 1;
        }
        catch (RuntimeException ignored) { /* Unknown diary state remains blocked until the next refresh. */ }
        Boolean member = null;
        try
        {
            // Subscription days also identify members visiting a free world.
            member = QuestAvailability.membershipFrom(client.getVarpValue(VarPlayer.MEMBERSHIP_DAYS),
                client.getWorldType().contains(WorldType.MEMBERS));
        }
        catch (RuntimeException ignored) { /* Retry unknown membership on the next refresh. */ }
        Map<String, Boolean> completedDiaries = new java.util.LinkedHashMap<>();
        DiaryCatalog.COMPLETION_VARBITS.forEach((id, varbit) ->
        {
            try { completedDiaries.put(id, client.getVarbitValue(varbit) == 1); }
            catch (RuntimeException ignored) { /* Retry missing diary data on the next refresh. */ }
        });
        Map<net.runelite.api.Skill, Integer> levels = new EnumMap<>(net.runelite.api.Skill.class);
        for (net.runelite.api.Skill skill : net.runelite.api.Skill.values())
        {
            if (skill == net.runelite.api.Skill.OVERALL) continue;
            try { levels.put(skill, client.getRealSkillLevel(skill)); }
            catch (RuntimeException ignored) { /* Missing skill data remains blocked. */ }
        }
        Integer combat = null;
        Integer questPoints = null;
        try
        {
            combat = client.getLocalPlayer().getCombatLevel();
            questPoints = client.getVarpValue(net.runelite.api.gameval.VarPlayerID.QP);
        }
        catch (RuntimeException ignored) { /* Retry after the next refresh. */ }
        Map<Integer, Integer> varps = new java.util.HashMap<>();
        Map<Integer, Integer> varbits = new java.util.HashMap<>();
        DiaryRequirements.Evaluation diaries = DiaryRequirements.evaluate(levels, states, combat, questPoints,
            id -> readDiaryVariable(varps, id, false), id -> readDiaryVariable(varbits, id, true));
        // Zamorak's chamber accepts a Hitpoints boost; diary evaluation above uses base levels.
        try
        {
            net.runelite.api.Skill hp = net.runelite.api.Skill.HITPOINTS;
            Integer base = levels.get(hp);
            if (base != null) levels.put(hp, Math.max(base, client.getBoostedSkillLevel(hp)));
        }
        catch (RuntimeException ignored) { /* Retain the known base level. */ }
        publish(new QuestAvailability(true, client.getAccountHash(), states, wildernessMediumComplete, member, completedDiaries,
            diaries.reasons, diaries.details, levels, BossAccess.read(client)));
    }

    private Integer readDiaryVariable(Map<Integer, Integer> cache, int id, boolean varbit)
    {
        if (!cache.containsKey(id))
        {
            Integer value = null;
            try { value = varbit ? client.getVarbitValue(id) : client.getVarpValue(id); }
            catch (RuntimeException ignored) { /* Failed reads never waive task requirements. */ }
            cache.put(id, value);
        }
        return cache.get(id);
    }

    private void publish(QuestAvailability snapshot)
    {
        if (snapshot.equals(lastSnapshot)) return;
        lastSnapshot = snapshot;
        int token = generation.get();
        SwingUtilities.invokeLater(() ->
        {
            if (token == generation.get() && active && panel != null) panel.updateAvailability(snapshot);
        });
    }

}

package com.osrsrandomizer;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.Arrays;
import java.util.HashSet;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/** Immutable snapshot. Unknown/unmapped requirements are never declared completed. */
final class QuestAvailability
{
    private static final Map<String, Quest> REQUIREMENTS;
    private static final Set<String> MEMBERS_SKILLS = new HashSet<>(Arrays.asList(
        "agility", "construction", "farming", "fletching", "herblore", "hunter", "sailing", "slayer", "thieving"));
    private static final Set<String> FREE_BOSSES = new HashSet<>(Arrays.asList("brutus", "obor", "bryophyta"));
    private static final Set<String> WILDERNESS_MEDIUM_BOSSES = Collections.unmodifiableSet(
        new HashSet<>(Arrays.asList("artio", "spindel", "calvarion")));
    static
    {
        Map<String, Quest> rules = new LinkedHashMap<>();
        rules.put("skills:sailing", Quest.PANDEMONIUM);
        rules.put("skills:herblore", Quest.DRUIDIC_RITUAL);
        rules.put("bosses:mad_angel", Quest.FALLEN_FROM_GRACE);
        rules.put("bosses:maggot_king", Quest.THE_BLOOD_MOON_RISES);
        rules.put("bosses:brutus", Quest.THE_IDES_OF_MILK);
        rules.put("bosses:shellbane_gryphon", Quest.TROUBLED_TORTUGANS);
        rules.put("bosses:perilous_moons", Quest.PERILOUS_MOONS);
        rules.put("bosses:doom_of_mokhaiotl", Quest.THE_FINAL_DAWN);
        rules.put("bosses:yama", Quest.A_KINGDOM_DIVIDED);
        rules.put("bosses:nex", Quest.THE_FROZEN_DOOR);
        rules.put("bosses:the_hueycoatl", Quest.CHILDREN_OF_THE_SUN);
        rules.put("bosses:sol_heredit", Quest.CHILDREN_OF_THE_SUN);
        for (String id : new String[] {"barrows", "the_nightmare", "phosanis_nightmare"})
            rules.put("bosses:" + id, Quest.PRIEST_IN_PERIL);
        rules.put("raids:tob", Quest.PRIEST_IN_PERIL);
        rules.put("bosses:vorkath", Quest.DRAGON_SLAYER_II);
        rules.put("bosses:phantom_muspah", Quest.SECRETS_OF_THE_NORTH);
        for (String id : new String[] {"duke_sucellus", "the_leviathan", "the_whisperer", "vardorvis"})
            rules.put("bosses:" + id, Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE);
        for (String id : new String[] {"crystalline_hunllef", "corrupted_hunllef", "zalcano"})
            rules.put("bosses:" + id, Quest.SONG_OF_THE_ELVES);
        rules.put("bosses:amoxliatl", Quest.THE_HEART_OF_DARKNESS);
        rules.put("bosses:deranged_archaeologist", Quest.BONE_VOYAGE);
        rules.put("raids:toa", Quest.BENEATH_CURSED_SANDS);
        rules.put("raids:tfa", Quest.WHILE_GUTHIX_SLEEPS);
        REQUIREMENTS = Collections.unmodifiableMap(rules);
    }

    private final boolean ready;
    private final long account;
    private final Map<Quest, QuestState> states;
    private final Boolean wildernessMediumComplete;
    private final Boolean member;
    private final Map<String, Boolean> completedDiaries;
    private final Map<String, String> diaryRequirements;
    private final Map<String, String> diaryDetails;
    private final Map<Skill, Integer> levels;
    private final Map<String, String> bossAccess;

    QuestAvailability(boolean ready, long account, Map<Quest, QuestState> states)
    {
        this(ready, account, states, null);
    }

    QuestAvailability(boolean ready, long account, Map<Quest, QuestState> states, Boolean wildernessMediumComplete)
    {
        this(ready, account, states, wildernessMediumComplete, null);
    }

    QuestAvailability(boolean ready, long account, Map<Quest, QuestState> states, Boolean wildernessMediumComplete, Boolean member)
    {
        this(ready, account, states, wildernessMediumComplete, member, Collections.emptyMap());
    }

    QuestAvailability(boolean ready, long account, Map<Quest, QuestState> states, Boolean wildernessMediumComplete,
        Boolean member, Map<String, Boolean> completedDiaries)
    {
        this(ready, account, states, wildernessMediumComplete, member, completedDiaries, Collections.emptyMap());
    }

    QuestAvailability(boolean ready, long account, Map<Quest, QuestState> states, Boolean wildernessMediumComplete,
        Boolean member, Map<String, Boolean> completedDiaries, Map<String, String> diaryRequirements)
    {
        this(ready, account, states, wildernessMediumComplete, member, completedDiaries, diaryRequirements, Collections.emptyMap());
    }

    QuestAvailability(boolean ready, long account, Map<Quest, QuestState> states, Boolean wildernessMediumComplete,
        Boolean member, Map<String, Boolean> completedDiaries, Map<String, String> diaryRequirements, Map<String, String> diaryDetails)
    {
        this(ready, account, states, wildernessMediumComplete, member, completedDiaries, diaryRequirements, diaryDetails, Collections.emptyMap());
    }

    QuestAvailability(boolean ready, long account, Map<Quest, QuestState> states, Boolean wildernessMediumComplete,
        Boolean member, Map<String, Boolean> completedDiaries, Map<String, String> diaryRequirements,
        Map<String, String> diaryDetails, Map<Skill, Integer> levels)
    {
        this(ready, account, states, wildernessMediumComplete, member, completedDiaries, diaryRequirements,
            diaryDetails, levels, Collections.emptyMap());
    }

    QuestAvailability(boolean ready, long account, Map<Quest, QuestState> states, Boolean wildernessMediumComplete,
        Boolean member, Map<String, Boolean> completedDiaries, Map<String, String> diaryRequirements,
        Map<String, String> diaryDetails, Map<Skill, Integer> levels, Map<String, String> bossAccess)
    {
        this.bossAccess = Collections.unmodifiableMap(new LinkedHashMap<>(bossAccess));
        this.ready = ready;
        this.account = account;
        Map<Quest, QuestState> copy = new EnumMap<>(Quest.class);
        copy.putAll(states);
        this.states = Collections.unmodifiableMap(copy);
        this.wildernessMediumComplete = wildernessMediumComplete;
        this.member = member;
        this.completedDiaries = Collections.unmodifiableMap(new LinkedHashMap<>(completedDiaries));
        this.diaryRequirements = Collections.unmodifiableMap(new LinkedHashMap<>(diaryRequirements));
        this.diaryDetails = Collections.unmodifiableMap(new LinkedHashMap<>(diaryDetails));
        Map<Skill, Integer> levelCopy = new EnumMap<>(Skill.class);
        levelCopy.putAll(levels);
        this.levels = Collections.unmodifiableMap(levelCopy);
    }

    String requirementDetails(Category category, String id)
    {
        if (category == Category.DIARIES) return diaryDetails(id);
        if (!ready) return "Log in to view character requirements.";
        java.util.List<String> missing = new java.util.ArrayList<>();
        if (membersOnly(category, id))
        {
            if (member == null) missing.add("Membership: waiting for character data.");
            else if (!member) missing.add("Members only: an active membership is required.");
        }
        Quest quest = REQUIREMENTS.get(category.getKey() + ":" + id);
        if (quest != null && states.get(quest) != QuestState.FINISHED)
        {
            QuestState state = states.get(quest);
            missing.add("Complete " + quest.getName() + " ("
                + (state == null ? "waiting for quest data" : state == QuestState.IN_PROGRESS ? "in progress" : "not started") + ")");
        }
        if (needsWildernessMedium(category, id) && !Boolean.TRUE.equals(wildernessMediumComplete))
            missing.add("Complete the Medium Wilderness Diary ("
                + (wildernessMediumComplete == null ? "waiting for diary data" : "not completed") + ")");
        Skill skill = requiredSkill(category, id);
        if (skill != null)
        {
            Integer level = levels.get(skill);
            int required = requiredLevel(id);
            if (level == null || level < required)
                missing.add(skill.getName() + ": " + (level == null ? "?" : level) + " / " + required);
        }
        if (category == Category.BOSSES && BossAccess.IDS.contains(id))
        {
            String access = bossAccess.containsKey(id) ? bossAccess.get(id) : "Waiting for boss access data";
            if (access != null) missing.add(access);
        }
        String detail = missing.isEmpty() ? "No missing tracked requirements." : String.join("\n\n", missing);
        if (category == Category.BOSSES && BossAccess.GOD_WARS.contains(id))
            detail += "\n\nAlso needs a route to God Wars (defeat Dad during Troll Stronghold or use Ghommal's hilt), entry equipment and kill count/key. These are not checked.";
        if (!isChecked(category, id)) detail += "\n\nNo quest or diary requirements are tracked for this activity.";
        return detail;
    }

    String diaryDetails(String id)
    {
        if (!ready) return "Log in to view character requirements.";
        if (Boolean.TRUE.equals(completedDiaries.get(id))) return "Diary already completed.";
        String status = reason(Category.DIARIES, id);
        String detail = diaryDetails.get(id);
        return (status != null && (status.startsWith("Waiting") || status.equals("Members only")) ? status + "\n\n" : "")
            + (detail == null ? "Waiting for requirement details." : detail)
            + "\n\nCompleted tasks are ignored. Base levels only; boosts, items and some unlocks are not checked.";
    }

    static QuestAvailability unavailable()
    {
        return new QuestAvailability(false, -1, Collections.emptyMap());
    }

    static Set<Quest> quests()
    {
        Set<Quest> quests = EnumSet.copyOf(REQUIREMENTS.values());
        quests.addAll(DiaryRequirements.quests());
        return Collections.unmodifiableSet(quests);
    }
    boolean isReady() { return ready; }
    long account() { return account; }
    boolean isChecked(Category category, String id)
    {
        return (category == Category.DIARIES && DiaryCatalog.COMPLETION_VARBITS.containsKey(id))
            || REQUIREMENTS.containsKey(category.getKey() + ":" + id) || needsWildernessMedium(category, id)
            || requiredSkill(category, id) != null || (category == Category.BOSSES && BossAccess.IDS.contains(id));
    }

    private static Skill requiredSkill(Category category, String id)
    {
        if (category != Category.BOSSES) return null;
        switch (id)
        {
            case "tempoross": return Skill.FISHING;
            case "wintertodt": return Skill.FIREMAKING;
            case "shellbane_gryphon": return Skill.SLAYER;
            case "general_graardor": return Skill.STRENGTH;
            case "commander_zilyana": return Skill.AGILITY;
            case "kree_arra": return Skill.RANGED;
            case "kril_tsutsaroth": return Skill.HITPOINTS;
            default: return null;
        }
    }

    private static int requiredLevel(String id)
    {
        return id.equals("tempoross") ? 35 : id.equals("wintertodt") ? 50 : id.equals("shellbane_gryphon") ? 51 : 70;
    }

    private boolean needsWildernessMedium(Category category, String id)
    {
        return category == Category.BOSSES && WILDERNESS_MEDIUM_BOSSES.contains(id);
    }

    static boolean membersOnly(Category category, String id)
    {
        if (category == Category.SKILLS) return MEMBERS_SKILLS.contains(id);
        if (category == Category.BOSSES) return !FREE_BOSSES.contains(id);
        return category == Category.RAIDS || category == Category.DIARIES;
    }

    static Boolean membershipFrom(int days, boolean membersWorld)
    {
        if (membersWorld || days > 0) return true;
        return days == 0 ? Boolean.FALSE : null;
    }

    String reason(Category category, String id)
    {
        if (membersOnly(category, id))
        {
            if (!ready || member == null) return "Waiting for membership data";
            if (!member) return "Members only";
        }
        if (category == Category.DIARIES)
        {
            Boolean complete = completedDiaries.get(id);
            if (!ready || complete == null) return "Waiting for diary data";
            if (complete) return "Diary already completed";
            return diaryRequirements.containsKey(id) ? diaryRequirements.get(id) : "Waiting for skill/quest data";
        }
        if (needsWildernessMedium(category, id))
        {
            if (!ready || wildernessMediumComplete == null) return "Waiting for diary data";
            return wildernessMediumComplete ? null : "Complete the Medium Wilderness Diary";
        }
        Skill skill = requiredSkill(category, id);
        if (skill != null)
        {
            Integer level = levels.get(skill);
            if (!ready || level == null) return "Waiting for skill data";
            if (level < requiredLevel(id)) return "Requires " + requiredLevel(id) + " " + skill.getName();
        }
        Quest quest = REQUIREMENTS.get(category.getKey() + ":" + id);
        if (quest != null)
        {
            if (!ready || states.get(quest) == null) return "Waiting for quest data";
            if (states.get(quest) != QuestState.FINISHED) return "Complete " + quest.getName();
        }
        if (category == Category.BOSSES && BossAccess.IDS.contains(id))
            return bossAccess.containsKey(id) ? bossAccess.get(id) : "Waiting for boss access data";
        return null;
    }

    @Override public boolean equals(Object other)
    {
        if (!(other instanceof QuestAvailability)) return false;
        QuestAvailability that = (QuestAvailability) other;
        return ready == that.ready && account == that.account && states.equals(that.states)
            && Objects.equals(wildernessMediumComplete, that.wildernessMediumComplete)
            && Objects.equals(member, that.member) && completedDiaries.equals(that.completedDiaries)
            && diaryRequirements.equals(that.diaryRequirements) && diaryDetails.equals(that.diaryDetails) && levels.equals(that.levels) && bossAccess.equals(that.bossAccess);
    }

    @Override public int hashCode() { return Objects.hash(ready, account, states, wildernessMediumComplete, member, completedDiaries, diaryRequirements, diaryDetails, levels, bossAccess); }
}

package com.osrsrandomizer;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.GridLayout;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.ButtonGroup;
import javax.swing.JButton;
import javax.swing.JComboBox;

import javax.swing.Timer;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToggleButton;
import javax.swing.SwingConstants;
import net.runelite.client.ui.PluginPanel;

final class RandomizerPanel extends PluginPanel
{
    private static final Color BACKGROUND = new Color(35, 32, 26);
    private static final Color GOLD = new Color(226, 193, 116);
    private final DrawEngine engine;
    private final SelectionStore store;
    private final Map<Category, Set<String>> selections = new EnumMap<>(Category.class);
    private final Map<Category, Activity> results = new EnumMap<>(Category.class);
    private final Map<Category, Deque<Activity>> history = new EnumMap<>(Category.class);
    private final JPanel historyRows = new JPanel(new GridLayout(0, 1, 0, 2));
    private final Timer animation = new Timer(90, e -> advanceAnimation());
    private final List<Activity> previewPool = new ArrayList<>();
    private int animationFrame;
    private final ActivityIcons icons = new ActivityIcons();
    private Category category = Category.SKILLS;
    private final JPanel activities = new JPanel();
    private final JLabel count = new JLabel();
    private final JLabel shown = new JLabel();
    private final JLabel result = new JLabel("", SwingConstants.CENTER);
    private final JButton draw = new JButton("Draw");
    private boolean questFilterEnabled;
    private final JLabel syncStatus = new JLabel();
    private QuestAvailability availability = QuestAvailability.unavailable();
    private Long lastAccount;
    private String expandedRequirement;
    private final JComboBox<String> filter = new JComboBox<>(new String[] {"Show all", "Selected only", "Excluded only"});

    RandomizerPanel(DrawEngine engine, SelectionStore store)
    {
        this.engine = engine;
        this.store = store;
        for (Category c : Category.values())
        {
            selections.put(c, new LinkedHashSet<>(store.load(c)));
            history.put(c, new ArrayDeque<>());
        }
        setLayout(new BorderLayout(0, 8));
        setBackground(BACKGROUND);
        setBorder(BorderFactory.createEmptyBorder(10, 6, 10, 6));
        JPanel header = new JPanel(new BorderLayout(0, 8));
        header.setOpaque(false);
        JLabel title = new JLabel("OSRS RANDOMIZER", SwingConstants.CENTER);
        title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
        title.setForeground(GOLD);
        header.add(title, BorderLayout.NORTH);

        JPanel controls = new JPanel();
        controls.setOpaque(false);
        controls.setLayout(new javax.swing.BoxLayout(controls, javax.swing.BoxLayout.Y_AXIS));
        JPanel tabs = new JPanel(new GridLayout(1, Category.values().length, 3, 0));
        tabs.setOpaque(false);
        ButtonGroup group = new ButtonGroup();
        for (Category c : Category.values())
        {
            JToggleButton tab = tile(c.toString());
            tab.setIcon(icons.category(c));
            tab.setFont(tab.getFont().deriveFont(10f));
            tab.setPreferredSize(new Dimension(50, 50));
            tab.setSelected(c == category);
            tab.addActionListener(e ->
            {
                category = c;
                filter.setSelectedIndex(0);
                rebuild();
            });
            group.add(tab);
            tabs.add(tab);
        }
        controls.add(tabs);
        result.setForeground(GOLD);
        result.setFont(result.getFont().deriveFont(Font.BOLD, 18f));
        result.setIconTextGap(10);
        result.setHorizontalTextPosition(SwingConstants.CENTER);
        result.setVerticalTextPosition(SwingConstants.BOTTOM);
        JPanel resultBox = new JPanel(new BorderLayout());
        resultBox.setOpaque(false);
        resultBox.setBorder(BorderFactory.createEmptyBorder(8, 0, 8, 0));
        resultBox.setPreferredSize(new Dimension(210, 145));
        resultBox.add(result);
        controls.add(resultBox);
        JPanel drawBox = new JPanel(new GridLayout(1, 1));
        drawBox.add(draw);
        controls.add(drawBox);
        JLabel historyTitle = new JLabel("Recent draws");
        historyTitle.setForeground(GOLD);
        historyTitle.setBorder(BorderFactory.createEmptyBorder(5, 0, 4, 0));
        controls.add(historyTitle);
        historyRows.setOpaque(false);
        historyRows.setName("recentDraws");
        historyRows.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));
        controls.add(historyRows);
        questFilterEnabled = store.questFilterEnabled();
        syncStatus.setBorder(BorderFactory.createEmptyBorder(2, 0, 5, 0));
        controls.add(syncStatus);
        filter.getAccessibleContext().setAccessibleName("Selection filter");
        controls.add(filter);
        controls.add(count);
        JPanel selectionActions = new JPanel(new GridLayout(1, 2, 5, 0));
        selectionActions.setOpaque(false);
        JButton all = new JButton("All");
        JButton none = new JButton("None");
        all.setToolTipText("Include every activity in this category, including hidden activities");
        none.setToolTipText("Exclude every activity in this category, including hidden activities");
        all.addActionListener(e -> selectAll(true));
        none.addActionListener(e -> selectAll(false));
        selectionActions.add(all);
        selectionActions.add(none);
        controls.add(selectionActions);
        shown.setBorder(BorderFactory.createEmptyBorder(5, 0, 0, 0));
        controls.add(shown);
        for (java.awt.Component component : controls.getComponents())
            ((javax.swing.JComponent) component).setAlignmentX(0f);
        header.add(controls, BorderLayout.CENTER);
        add(header, BorderLayout.NORTH);
        activities.setOpaque(false);
        activities.setLayout(new javax.swing.BoxLayout(activities, javax.swing.BoxLayout.Y_AXIS));
        add(activities, BorderLayout.CENTER);
        JLabel hint = new JLabel("<html><small>Click an activity to include or exclude it.<br>Gold rows are included in the draw.</small></html>");
        add(hint, BorderLayout.SOUTH);
        filter.addActionListener(e -> rebuild());
        draw.addActionListener(e -> startDraw());
        rebuild();
    }

    private JToggleButton tile(String text)
    {
        JToggleButton button = new JToggleButton(text)
        {
            @Override protected void paintComponent(Graphics g)
            {
                g.setColor(!isEnabled() ? new Color(40, 40, 40)
                    : isSelected() ? new Color(91, 79, 49) : new Color(46, 41, 32));
                g.fillRect(0, 0, getWidth(), getHeight());
                super.paintComponent(g);
                if (Boolean.TRUE.equals(getClientProperty("locked")))
                {
                    // A small drawn icon stays crisp without relying on emoji font support.
                    Graphics lock = g.create();
                    lock.setColor(GOLD);
                    int x = getWidth() - 18;
                    int y = (getHeight() - 14) / 2;
                    lock.drawRoundRect(x + 3, y, 6, 9, 5, 5);
                    lock.fillRect(x + 1, y + 6, 11, 8);
                    lock.setColor(BACKGROUND);
                    lock.fillRect(x + 6, y + 9, 1, 3);
                    lock.dispose();
                }
            }
        };
        button.setContentAreaFilled(false);
        button.setForeground(new Color(235, 224, 197));
        button.setHorizontalTextPosition(SwingConstants.CENTER);
        button.setVerticalTextPosition(SwingConstants.BOTTOM);
        button.setIconTextGap(6);
        button.setBorder(BorderFactory.createLineBorder(new Color(68, 60, 45)));
        button.addItemListener(e -> button.setBorder(BorderFactory.createLineBorder(
            button.isSelected() ? new Color(180, 151, 84) : new Color(68, 60, 45))));
        return button;
    }

    private void selectAll(boolean selected)
    {
        Set<String> ids = selections.get(category);
        ids.clear();
        if (selected) for (Activity activity : category.getActivities()) ids.add(activity.getId());
        store.save(category, ids);
        rebuild();
    }

    private static String shortReason(String reason)
    {
        String[] parts = reason.split("; ");
        return parts[0] + (parts.length > 1 ? " (+" + (parts.length - 1) + " more)" : "");
    }

    private void rebuild()
    {
        cancelAnimation();
        activities.removeAll();
        int visible = 0;
        for (Activity activity : category.getActivities())
        {
            String reason = blockedReason(activity.getId());
            boolean included = selections.get(category).contains(activity.getId()) && reason == null;
            if ( (filter.getSelectedIndex() == 1 && !included)
                || (filter.getSelectedIndex() == 2 && included)) continue;
            boolean locked = reason != null && !reason.startsWith("Waiting");
            JToggleButton card = tile("<html><div style='width:125px'>"
                + (reason == null ? activity.getName() : "<font color='#c6c0b4'>" + activity.getName() + "</font>")
                + (reason == null ? "" : "<br><font color='#d8bc7c'><small>"
                    + (locked ? shortReason(reason) : "Checking requirements...")
                    + "</small></font>") + "</div></html>");
            card.setHorizontalAlignment(SwingConstants.LEFT);
            card.setHorizontalTextPosition(SwingConstants.RIGHT);
            card.setVerticalTextPosition(SwingConstants.CENTER);
            card.setIconTextGap(8);
            card.putClientProperty("activityId", activity.getId());
            card.putClientProperty("locked", locked);
            card.getAccessibleContext().setAccessibleName(activity.getName());
            card.getAccessibleContext().setAccessibleDescription(reason);
            card.setIcon(icons.activity(category, activity, 20));
            int rowHeight = Math.max(reason == null ? 38 : 48, card.getPreferredSize().height + 12);
            card.setPreferredSize(new Dimension(210, rowHeight));
            card.setMaximumSize(new Dimension(Integer.MAX_VALUE, rowHeight));
            card.setAlignmentX(0f);
            card.setSelected(included);
            card.setEnabled(reason == null);
            card.setToolTipText(reason != null ? (reason.contains("; ") ? "<html>" + reason.replace("; ", "<br>") + "</html>" : reason) : activity.getName() + (included ? " — included" : " — excluded")
                + (questFilterEnabled && !availability.isChecked(category, activity.getId())
                    ? " (requirements not checked)" : ""));
            card.addActionListener(e ->
            {
                cancelAnimation();
                Set<String> ids = selections.get(category);
                if (card.isSelected()) ids.add(activity.getId()); else ids.remove(activity.getId());
                store.save(category, ids);
                if (filter.getSelectedIndex() != 0) rebuild();
                else
                {
                    card.setToolTipText(activity.getName() + (card.isSelected() ? " — included" : " — excluded"));
                    refresh();
                }
            });
            if (visible > 0) activities.add(javax.swing.Box.createVerticalStrut(3));
            {
                JPanel row = new JPanel(new BorderLayout(3, 0));
                row.setOpaque(false);
                row.setAlignmentX(0f);
                row.setMaximumSize(new Dimension(Integer.MAX_VALUE, rowHeight));
                row.add(card, BorderLayout.CENTER);
                JButton info = new JButton("i");
                info.setMargin(new java.awt.Insets(0, 0, 0, 0));
                info.setPreferredSize(new Dimension(23, rowHeight));
                info.setToolTipText("Show missing requirements");
                info.getAccessibleContext().setAccessibleName("Requirements: " + activity.getName());
                info.putClientProperty("requirementInfo", activity.getId());
                if (category == Category.DIARIES) info.putClientProperty("diaryInfo", activity.getId());
                String detailKey = category.getKey() + ":" + activity.getId();
                info.addActionListener(e -> {
                    expandedRequirement = detailKey.equals(expandedRequirement) ? null : detailKey;
                    rebuild();
                });
                row.add(info, BorderLayout.EAST);
                activities.add(row);
                if (detailKey.equals(expandedRequirement))
                {
                    String text = availability.requirementDetails(category, activity.getId());
                    JLabel detail = new JLabel("<html><div style='width:145px'><b>Missing requirements</b><br>"
                        + escapeHtml(text).replace("\n", "<br>") + "</div></html>");
                    detail.putClientProperty("requirementDetails", activity.getId());
                    if (category == Category.DIARIES) detail.putClientProperty("diaryDetails", activity.getId());
                    detail.setForeground(new Color(216, 202, 174));
                    detail.setBorder(BorderFactory.createEmptyBorder(8, 6, 10, 6));
                    detail.setAlignmentX(0f);
                    detail.setMaximumSize(new Dimension(Integer.MAX_VALUE, detail.getPreferredSize().height));
                    activities.add(detail);
                }
            }
            visible++;
        }

        shown.setText(visible == 0 ? "No matching activities" : visible + " activities shown");
        refresh();
        revalidate();
        repaint();
    }

    private static String escapeHtml(String text)
    {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private void refresh()
    {
        int size = effectiveSelection().size();
        count.setText(size + " / " + category.getActivities().size() + " included");
        boolean waiting = questFilterEnabled && !availability.isReady();
        syncStatus.setText(questFilterEnabled
            ? (waiting ? "<html><small>Log in to sync character data.</small></html>"
                : "<html><small>Character checks · partial coverage</small></html>") : "");
        draw.setEnabled(size > 0 && !waiting && !animation.isRunning());
        draw.setText(animation.isRunning() ? "Drawing..." : "Draw");
        Activity previous = results.get(category);
        if (!animation.isRunning())
        {
        result.setIcon(size > 0 && previous != null ? icons.activity(category, previous, 48) : icons.category(category));
        String message = waiting ? "Log in to sync" : size == 0 ? "No eligible activities selected" : previous == null
            ? "No draw yet" : previous.getName();
        result.setText("<html><div style='width:145px;text-align:center'>" + message + "</div></html>");
        }
        historyRows.removeAll();
        int position = 0;
        for (Activity activity : history.get(category))
        {
            JLabel row = new JLabel("<html><div style='width:125px'>" + (++position) + ". " + activity.getName() + "</div></html>",
                icons.activity(category, activity, 18), SwingConstants.LEFT);
            row.setToolTipText(activity.getName());
            historyRows.add(row);
        }
        if (position == 0) historyRows.add(new JLabel("No draws yet"));
        revalidate();
        repaint();
    }

    private void startDraw()
    {
        if (animation.isRunning() || effectiveSelection().isEmpty()
            || (questFilterEnabled && !availability.isReady())) return;
        previewPool.clear();
        for (Activity activity : category.getActivities())
            if (effectiveSelection().contains(activity.getId())) previewPool.add(activity);
        if (previewPool.size() < 2)
        {
            finishDraw();
            return;
        }
        animationFrame = 0;
        animation.start();
        advanceAnimation();
        refresh();
    }

    // Runs on the Swing EDT. Preview frames never enter the draw engine or history.
    void advanceAnimation()
    {
        if (!animation.isRunning()) return;
        if (animationFrame == 9)
        {
            finishDraw();
            return;
        }
        Activity preview = previewPool.get(animationFrame++ % previewPool.size());
        result.setIcon(icons.activity(category, preview, 48));
        result.setText("<html><div style='width:145px;text-align:center'>" + preview.getName() + "</div></html>");
    }

    private void finishDraw()
    {
        animation.stop();
        previewPool.clear();
        engine.draw(category, effectiveSelection()).ifPresent(activity ->
        {
            results.put(category, activity);
            Deque<Activity> recent = history.get(category);
            recent.addFirst(activity);
            while (recent.size() > 5) recent.removeLast();
            if (lastAccount != null)
                store.saveHistory(lastAccount, category, HistoryCodec.encode(recent));
        });
        refresh();
    }

    private void cancelAnimation()
    {
        animation.stop();
        previewPool.clear();
    }

    void dispose() { cancelAnimation(); }

    void setQuestFilterEnabled(boolean enabled)
    {
        if (questFilterEnabled == enabled) return;
        questFilterEnabled = enabled;
        rebuild();
    }

    private String blockedReason(String id)
    {
        return questFilterEnabled ? availability.reason(category, id) : null;
    }

    private Set<String> effectiveSelection()
    {
        Set<String> selected = new LinkedHashSet<>(selections.get(category));
        if (questFilterEnabled) selected.removeIf(id -> availability.reason(category, id) != null);
        return selected;
    }

    void updateAvailability(QuestAvailability snapshot)
    {
        if (availability.equals(snapshot)) return;
        availability = snapshot;
        if (!snapshot.isReady())
        {
            lastAccount = null;
            results.clear();
            for (Deque<Activity> entries : history.values()) entries.clear();
            engine.reset();
        }
        else if (lastAccount == null || lastAccount.longValue() != snapshot.account())
        {
            results.clear();
            engine.reset();
            for (Category c : Category.values())
            {
                Deque<Activity> entries = history.get(c);
                entries.clear();
                entries.addAll(HistoryCodec.decode(c, store.loadHistory(snapshot.account(), c)));
                if (!entries.isEmpty()) results.put(c, entries.getFirst());
                engine.restore(c, entries);
            }
            lastAccount = snapshot.account();
        }
        rebuild();
    }
}

package com.osrsrandomizer;

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.stream.Collectors;

final class SelectionCodec
{
    static Set<String> decode(Category category, String value)
    {
        Set<String> valid = category.getActivities().stream().map(Activity::getId)
            .collect(Collectors.toCollection(LinkedHashSet::new));
        if (value == null) return valid;
        valid.retainAll(Arrays.asList(value.split(",")));
        return valid;
    }

    static String encode(Set<String> selected) { return String.join(",", selected); }
}

package com.osrsrandomizer;

import java.util.Set;

interface SelectionStore
{
    default boolean questFilterEnabled() { return true; }
    Set<String> load(Category category);
    void save(Category category, Set<String> selected);
    default String loadHistory(long account, Category category) { return null; }
    default void saveHistory(long account, Category category, String value) { }
}

package com.osrsrandomizer;

import java.util.*;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import static org.junit.Assert.*;

public class DiaryCatalogTest
{
    @Test public void catalogueHasAllTiersAndUsesKaramjaLegacyCompletionFlags()
    {
        assertEquals(48, Category.DIARIES.getActivities().size());
        assertEquals(48, new HashSet<>(DiaryCatalog.COMPLETION_VARBITS.values()).size());
        assertEquals(Integer.valueOf(VarbitID.ATJUN_EASY_DONE), DiaryCatalog.COMPLETION_VARBITS.get("karamja_easy"));
        assertEquals(Integer.valueOf(VarbitID.ATJUN_MED_DONE), DiaryCatalog.COMPLETION_VARBITS.get("karamja_medium"));
        assertEquals(Integer.valueOf(VarbitID.ATJUN_HARD_DONE), DiaryCatalog.COMPLETION_VARBITS.get("karamja_hard"));
        for (Activity activity : Category.DIARIES.getActivities())
        {
            assertTrue(DiaryCatalog.COMPLETION_VARBITS.containsKey(activity.getId()));
            Set<String> one = Collections.singleton(activity.getId());
            assertEquals(one, SelectionCodec.decode(Category.DIARIES, SelectionCodec.encode(one)));
            assertEquals(activity.getId(), new DrawEngine(new Random(1)).draw(Category.DIARIES, one).get().getId());
            assertEquals(activity.getId(), HistoryCodec.encode(HistoryCodec.decode(Category.DIARIES, activity.getId())));
        }
        assertTrue(SelectionCodec.decode(Category.DIARIES, "").isEmpty());
    }

    @Test public void completionSnapshotIsImmutableAndDistinguishesUnknownFreeAndFinished()
    {
        Map<String, Boolean> flags = new LinkedHashMap<>();
        DiaryCatalog.COMPLETION_VARBITS.keySet().forEach(id -> flags.put(id, false));
        QuestAvailability unfinished = snapshot(true, flags);
        flags.replaceAll((id, value) -> true);
        QuestAvailability completed = snapshot(true, flags);
        QuestAvailability free = snapshot(false, flags);
        QuestAvailability unknown = snapshot(true, Collections.emptyMap());
        for (String id : flags.keySet())
        {
            assertNull(unfinished.reason(Category.DIARIES, id));
            assertEquals("Diary already completed", completed.reason(Category.DIARIES, id));
            assertEquals("Members only", free.reason(Category.DIARIES, id));
            assertEquals("Waiting for diary data", unknown.reason(Category.DIARIES, id));
            assertEquals("Waiting for membership data", QuestAvailability.unavailable().reason(Category.DIARIES, id));
        }
        assertNotEquals(unfinished, completed);
        assertEquals(completed, snapshot(true, flags));
        assertEquals(completed.hashCode(), snapshot(true, flags).hashCode());
    }

    private QuestAvailability snapshot(boolean member, Map<String, Boolean> flags)
    {
        return new QuestAvailability(true, 1, Collections.emptyMap(), false, member, flags, DiaryRequirementsTest.eligible());
    }
}

package com.osrsrandomizer;

import java.util.*;
import net.runelite.api.*;
import net.runelite.client.plugins.achievementdiary.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class DiaryRequirementsTest
{
    @Test public void completedTaskWaivesOnlyItsOwnRequirements()
    {
        Map<Skill, Integer> levels = maxLevels();
        levels.put(Skill.THIEVING, 1);
        Map<Quest, QuestState> quests = finishedQuests();
        quests.put(Quest.BIOHAZARD, QuestState.NOT_STARTED);
        // Ardougne: cake task is bit 1, combat training camp is bit 6.
        DiaryRequirements.Evaluation cakeDone = DiaryRequirements.evaluate(levels, quests, 126, 999,
            id -> id == 1196 ? 1 << 1 : 0, id -> 0);
        assertEquals("Complete Biohazard", cakeDone.reasons.get("ardougne_easy"));
        assertFalse(cakeDone.details.get("ardougne_easy").contains("Thieving"));
        assertNull(DiaryRequirements.evaluate(levels, quests, 126, 999,
            id -> id == 1196 ? (1 << 1) | (1 << 6) : 0, id -> 0).reasons.get("ardougne_easy"));
        assertTrue(DiaryRequirements.evaluate(levels, quests, 126, 999,
            id -> null, id -> null).reasons.get("ardougne_easy").contains("5 Thieving"));
    }

    @Test public void partialKaramjaTaskDoesNotWaiveRequirements()
    {
        Map<Skill, Integer> levels = maxLevels();
        levels.put(Skill.WOODCUTTING, 1);
        // Collect FIVE palm leaves: 4 is incomplete, 5 complete.
        assertNotNull(DiaryRequirements.evaluate(levels, finishedQuests(), 126, 999,
            id -> 0, id -> id == 3607 ? 4 : 1).reasons.get("karamja_hard"));
        assertNull(DiaryRequirements.evaluate(levels, finishedQuests(), 126, 999,
            id -> 0, id -> id == 3607 ? 5 : 1).reasons.get("karamja_hard"));
    }

    @Test public void signBitCompletionAndUnknownReadsAreHandled()
    {
        DiaryTask task = DiaryRequirementsData.tasks().get("ardougne_hard").stream()
            .filter(t -> t.name.contains("Red Salamander")).findFirst().get();
        assertTrue(task.completed(id -> Integer.MIN_VALUE, id -> 0));
        assertFalse(task.completed(id -> Integer.MAX_VALUE, id -> 0));
        assertFalse(task.completed(id -> null, id -> null));
    }

    @Test public void completedTasksAcrossAllTiersIgnoreEvenUnknownRequirements()
    {
        DiaryRequirements.Evaluation allDone = DiaryRequirements.evaluate(Collections.emptyMap(), Collections.emptyMap(), null, null,
            id -> -1, id -> 100);
        assertEquals(48, allDone.reasons.size());
        allDone.reasons.values().forEach(reason -> assertNull(reason));
        allDone.details.values().forEach(detail -> assertEquals("No missing tracked requirements for unfinished tasks.", detail));
    }

    @Test public void detailsShowCurrentLevelsAndQuestStateAndRefreshOnLevelChange()
    {
        Map<Skill, Integer> levels = maxLevels();
        levels.put(Skill.THIEVING, 3);
        Map<Quest, QuestState> quests = finishedQuests();
        quests.put(Quest.BIOHAZARD, QuestState.IN_PROGRESS);
        DiaryRequirements.Evaluation first = DiaryRequirements.evaluate(levels, quests, 126, 999, id -> 0, id -> 0);
        String detail = first.details.get("ardougne_easy");
        assertTrue(detail.contains("Thieving: 3 / 5"));
        assertTrue(detail.contains("Complete Biohazard (in progress)"));
        levels.put(Skill.THIEVING, 4);
        DiaryRequirements.Evaluation second = DiaryRequirements.evaluate(levels, quests, 126, 999, id -> 0, id -> 0);
        assertEquals(first.reasons, second.reasons);
        assertNotEquals(new QuestAvailability(true, 1, quests, false, true, Collections.emptyMap(), first.reasons, first.details),
            new QuestAvailability(true, 1, quests, false, true, Collections.emptyMap(), second.reasons, second.details));
    }

    static Map<Skill, Integer> maxLevels()
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values()) levels.put(skill, 99);
        return levels;
    }

    static Map<Quest, QuestState> finishedQuests()
    {
        Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
        DiaryRequirements.quests().forEach(q -> quests.put(q, QuestState.FINISHED));
        return quests;
    }

    static Map<String, String> eligible()
    {
        return DiaryRequirements.evaluate(maxLevels(), finishedQuests(), 126, 999, id -> 0, id -> id == 1782 ? 999 : 0).reasons;
    }

    @Test public void all48TiersHaveRulesAndUnknownDataNeverUnlocks()
    {
        assertEquals(DiaryCatalog.COMPLETION_VARBITS.keySet(), DiaryRequirementsData.rules().keySet());
        assertEquals(48, eligible().size());
        eligible().values().forEach(reason -> assertNull(reason));
        DiaryRequirements.evaluate(Collections.emptyMap(), Collections.emptyMap(), null, null)
            .values().forEach(reason -> assertEquals("Waiting for skill/quest data", reason));
    }

    @Test public void skillBoundaryAndQuestCompletionUnlockArdougneEasy()
    {
        Map<Skill, Integer> levels = maxLevels();
        Map<Quest, QuestState> quests = finishedQuests();
        levels.put(Skill.THIEVING, 4);
        quests.put(Quest.BIOHAZARD, QuestState.IN_PROGRESS);
        String reason = DiaryRequirements.evaluate(levels, quests, 126, 999).get("ardougne_easy");
        assertTrue(reason.contains("5 Thieving"));
        assertTrue(reason.contains("Complete Biohazard"));
        levels.put(Skill.THIEVING, 5);
        assertEquals("Complete Biohazard", DiaryRequirements.evaluate(levels, quests, 126, 999).get("ardougne_easy"));
        quests.put(Quest.BIOHAZARD, QuestState.FINISHED);
        assertNull(DiaryRequirements.evaluate(levels, quests, 126, 999).get("ardougne_easy"));
    }

    @Test public void startedQuestIsDifferentFromCompletedQuest()
    {
        Quest quest = Quest.FAIRYTALE_II__CURE_A_QUEEN;
        for (QuestState state : QuestState.values())
        {
            Map<Quest, QuestState> states = Collections.singletonMap(quest, state);
            assertEquals(state != QuestState.NOT_STARTED,
                DiaryRequirements.satisfied(new QuestRequirement(quest, true), maxLevels(), states, 126, 999));
            assertEquals(state == QuestState.FINISHED,
                DiaryRequirements.satisfied(new QuestRequirement(quest), maxLevels(), states, 126, 999));
        }
    }

    @Test public void alternativeSkillsDoNotBecomeAnAndRequirement()
    {
        Map<Skill, Integer> levels = maxLevels();
        levels.put(Skill.AGILITY, 52);
        levels.put(Skill.STRENGTH, 60);
        assertNull(DiaryRequirements.evaluate(levels, finishedQuests(), 126, 999).get("wilderness_medium"));
        levels.put(Skill.STRENGTH, 59);
        assertTrue(DiaryRequirements.evaluate(levels, finishedQuests(), 126, 999)
            .get("wilderness_medium").contains("60 Agility or 60 Strength"));
        Requirement or = new OrRequirement(new SkillRequirement(Skill.AGILITY, 60), new SkillRequirement(Skill.STRENGTH, 60));
        levels.remove(Skill.AGILITY);
        assertNull(DiaryRequirements.satisfied(or, levels, finishedQuests(), 126, 999));
        levels.put(Skill.STRENGTH, 60);
        assertTrue(DiaryRequirements.satisfied(or, levels, finishedQuests(), 126, 999));
    }

    @Test public void combatAndQuestPointBoundariesAreChecked()
    {
        assertTrue(DiaryRequirements.evaluate(maxLevels(), finishedQuests(), 39, 31)
            .get("varrock_medium").contains("32 Quest points"));
        assertTrue(DiaryRequirements.evaluate(maxLevels(), finishedQuests(), 39, 32)
            .get("varrock_medium").contains("40 Combat"));
        assertNull(DiaryRequirements.evaluate(maxLevels(), finishedQuests(), 40, 32).get("varrock_medium"));
    }
}

package com.osrsrandomizer;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Collections;
import java.util.Deque;
import java.util.LinkedHashSet;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.Test;
import static org.junit.Assert.*;

public class DrawEngineTest
{
    private Set<String> first(int n)
    {
        return Category.SKILLS.getActivities().stream().limit(n).map(Activity::getId)
            .collect(Collectors.toCollection(LinkedHashSet::new));
    }

    @Test public void emptyAndUnknownSelectionsDoNotDraw()
    {
        DrawEngine engine = new DrawEngine(new Random(1));
        assertFalse(engine.draw(Category.SKILLS, Collections.emptySet()).isPresent());
        assertFalse(engine.draw(Category.SKILLS, Collections.singleton("unknown")).isPresent());
    }

    @Test public void smallAndLargePoolsRespectLongestPossibleWindow()
    {
        for (int n = 1; n <= 24; n++)
        {
            DrawEngine engine = new DrawEngine(new Random(n));
            Set<String> selected = first(n);
            Deque<String> recent = new ArrayDeque<>();
            for (int i = 0; i < 500; i++)
            {
                String id = engine.draw(Category.SKILLS, selected).get().getId();
                assertTrue(selected.contains(id));
                assertFalse("Pool " + n + " repeated inside protected window", recent.contains(id));
                recent.addLast(id);
                while (recent.size() > Math.min(3, n - 1)) recent.removeFirst();
            }
        }
    }

    @Test public void categoriesHaveIndependentHistory()
    {
        // A constant RNG makes history influence visible, without RNG interleaving effects.
        Random zero = new Random() { @Override public int nextInt(int bound) { return 0; } };
        DrawEngine engine = new DrawEngine(zero);
        String first = engine.draw(Category.SKILLS, first(5)).get().getId();
        Set<String> raids = SelectionCodec.decode(Category.RAIDS, null);
        for (int i = 0; i < 10; i++) engine.draw(Category.RAIDS, raids);
        assertNotEquals(first, engine.draw(Category.SKILLS, first(5)).get().getId());
    }

    @Test public void selectionChangesReleaseOldestFirstAndKeepMemory()
    {
        Random zero = new Random() { @Override public int nextInt(int bound) { return 0; } };
        DrawEngine engine = new DrawEngine(zero);
        Set<String> all = first(5);
        String a = engine.draw(Category.SKILLS, all).get().getId();
        String b = engine.draw(Category.SKILLS, all).get().getId();
        String c = engine.draw(Category.SKILLS, all).get().getId();
        assertFalse(engine.draw(Category.SKILLS, Collections.emptySet()).isPresent());
        assertEquals(b, engine.draw(Category.SKILLS, Arrays.asList(b, c)).get().getId());
        assertEquals(a, engine.draw(Category.SKILLS, all).get().getId());
    }

    @Test public void selectionsRoundTripIncludingExplicitEmpty()
    {
        assertEquals(24, SelectionCodec.decode(Category.SKILLS, null).size());
        assertTrue(SelectionCodec.decode(Category.SKILLS, "").isEmpty());
        assertEquals(first(3), SelectionCodec.decode(Category.SKILLS, SelectionCodec.encode(first(3))));
        assertEquals(Collections.singleton("attack"), SelectionCodec.decode(Category.SKILLS, "attack,unknown,attack"));
    }

    @Test public void catalogueIdsAreUniqueWithinEachCategory()
    {
        assertEquals(53, Category.BOSSES.getActivities().size());
        assertEquals(4, Category.RAIDS.getActivities().size());
        for (Category category : Category.values())
            assertEquals(category.getActivities().size(), SelectionCodec.decode(category, null).size());
    }

    @Test public void newRaidPreservesOldSelectionsAndCanBeDrawnAndSaved()
    {
        assertEquals(new LinkedHashSet<>(Arrays.asList("cox", "tob", "toa")),
            SelectionCodec.decode(Category.RAIDS, "cox,tob,toa"));
        assertFalse(SelectionCodec.decode(Category.RAIDS, "").contains("tfa"));
        assertTrue(SelectionCodec.decode(Category.RAIDS, null).contains("tfa"));
        Activity raid = new DrawEngine(new Random(1)).draw(Category.RAIDS, Collections.singleton("tfa")).get();
        assertEquals("The Fractured Archive", raid.getName());
        assertEquals("tfa", HistoryCodec.encode(HistoryCodec.decode(Category.RAIDS, "tfa")));
